import json
import pytest

TOLERANCE = 0.03
FLOORS = {"faithfulness": 0.85, "answer_relevance": 0.80}

@pytest.mark.parametrize("metric", ["faithfulness", "answer_relevance"])
def test_no_regression(metric: str, scores: dict[str, float]) -> None:
    baseline = json.load(open("evals/baseline.json"))
    current = scores[metric]
    assert current >= FLOORS[metric], f"{metric} below floor"
    if metric in baseline:
        assert current >= baseline[metric] - TOLERANCE, f"{metric} regressed"
